private void btnCalculateActionPerformed(java.awt.event.ActionEvent evt) {
    try {
        double baseFee = Double.parseDouble(txtConsultationFee.getText().trim());
        if (baseFee < 0) {
            javax.swing.JOptionPane.showMessageDialog(this, 
                "Consultation fee cannot be negative!", "Input Error", 
                javax.swing.JOptionPane.WARNING_MESSAGE);
            return;
        }

        // Step 1: Emergency Add-on
        double emergencyAddon = 0.0;
        if (rbEmergency.isSelected()) {
            emergencyAddon = 300.0;
        }

        // Step 2: ECG Add-on
        double ecgAddon = 0.0;
        if (chkECG.isSelected()) {
            ecgAddon = 400.0;
        }

        // Step 3: Total calculation
        double netPayable = baseFee + emergencyAddon + ecgAddon;

        // Step 4: Display
        txtNetPayable.setText(String.format("₹ %.2f", netPayable));

    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this, 
            "Please enter a valid numeric consultation fee!", "Error", 
            javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}
```

